 const [dicePrompt,setDicePrompt]=useState<DicePrompt|null>(null);const [face,setFace]=useState('');const [shown,setShown]=useState<DicePrompt[]>([]);
 const [diceHistory,setDiceHistory]=useState<{message:string;rolls:DicePrompt[]}[]>([]);const [overlay,setOverlay]=useState(false);const [autoDismiss,setAutoDismiss]=useState(true);const [turnNotices,setTurnNotices]=useState(true);const [notice,setNotice]=useState<string|null>(null);const [queuedTurn,setQueuedTurn]=useState<string|null>(null);
 function dismissOverlay(){if(queuedTurn){setNotice(queuedTurn);setQueuedTurn(null);setShown([]);}else{setOverlay(false);setNotice(null);}}
 useEffect(()=>{if(!overlay||dicePrompt||!autoDismiss)return;const timer=setTimeout(dismissOverlay,animate?2200:900);return()=>clearTimeout(timer);},[overlay,shown,dicePrompt,animate,autoDismiss,notice,queuedTurn]);
