 function resolveDice(){const tx=transaction.current;if(!tx)return;try{if(current.current!==tx.base)throw new Error('Encounter changed');const {result:r,rolls}=withDice(tx.faces,true,tx.fn);transaction.current=null;setDicePrompt(null);const next=r.state.turn;const prev=tx.base.turn;const changed=next&&r.state.status!=='completed'&&(!prev||next.round!==prev.round||next.slotIndex!==prev.slotIndex);const turnLabel=changed&&turnNotices?`Round ${next.round} · ${r.state.initiative[next.slotIndex].combatantIds.map(id=>r.state.combatants.find(c=>c.id===id)?.name??id).join(" / ")}`:null;setNotice(null);setQueuedTurn(null);if(turnLabel){if(rolls.length)setQueuedTurn(turnLabel);else{setNotice(turnLabel);setShown([]);setOverlay(true);}}if(rolls.length){setShown(diceMode==='digital'?[]:rolls);setDiceHistory(h=>[...h,{message:r.message,rolls}]);setOverlay(true);}current.current=r.state;setState(r.state);setLog(l=>[...l,...rolls.map(d=>`${d.label}: d${d.max} = ${d.value}`),r.message]);setError('');setDiceBusy(false);}catch(e){if(e instanceof PendingDice){setOverlay(true);setDicePrompt(e.prompt);setShown([]);setFace('');return;}transaction.current=null;setDicePrompt(null);setOverlay(false);setDiceBusy(false);setError(e instanceof Error?e.message:String(e));}}
 useEffect(()=>{if(diceMode!=='digital'||!dicePrompt||!autoDismiss)return;const timer=setTimeout(()=>submitFace(null),animate?1600:850);return()=>clearTimeout(timer);},[dicePrompt,diceMode,autoDismiss,animate]);
