 const [mode,setMode]=useState<"sandbox"|"roster">("sandbox");const [savedLeft,setSavedLeft]=useState("");const [savedRight,setSavedRight]=useState("");
 const [extraLeft,setExtraLeft]=useState('');const [extraRight,setExtraRight]=useState('');const [trainerHP,setTrainerHP]=useState(10);const [trainerAC,setTrainerAC]=useState(10);const [trainerPotions,setTrainerPotions]=useState(2);const [trainerAlly,setTrainerAlly]=useState('');const [trainerTab,setTrainerTab]=useState<'combat'|'support'|'inventory'>('combat');const [group,setGroup]=useState(false);const [actorChoice,setActorChoice]=useState('');const [targetChoice,setTargetChoice]=useState('');
