 const targets=state.combatants.filter(c=>c.kind==='pokemon'&&c.deployment==='active'&&c.currentHP>0&&c.sideId!==actor?.sideId);const target=targets.find(c=>c.id===targetChoice)??targets[0];
 const allies=state.combatants.filter(c=>c.kind==='pokemon'&&c.sideId===actor?.sideId&&c.currentHP>0&&c.deployment==='active');const ally=allies.find(c=>c.id===trainerAlly)??allies[0];
 const [pending,setPending]=useState<{version:number;id:string;position:Position;candidates:readonly string[]}|null>(null);
