 const [editorHistory,setEditorHistory]=useState<TerrainMap[]>([]);const [editorFuture,setEditorFuture]=useState<TerrainMap[]>([]);
 const [brushSize,setBrushSize]=useState(1);const [mapName,setMapName]=useState('Battlefield');const [editorZoom,setEditorZoom]=useState(32);
 const importRef=useRef<HTMLInputElement>(null);
 function commitTerrain(next:TerrainMap){setEditorHistory(old=>[...old.slice(-49),terrain]);setEditorFuture([]);setTerrain(next);}
 function undoTerrain(){if(!editorHistory.length)return;setEditorFuture(old=>[terrain,...old]);setTerrain(editorHistory[editorHistory.length-1]);setEditorHistory(old=>old.slice(0,-1));}
 function redoTerrain(){if(!editorFuture.length)return;setEditorHistory(old=>[...old,terrain]);setTerrain(editorFuture[0]);setEditorFuture(old=>old.slice(1));}
 function paintTerrain(p:Position){const next={...terrain};for(let dy=0;dy<brushSize;dy++)for(let dx=0;dx<brushSize;dx++){const q={...p,x:p.x+dx*5,y:p.y+dy*5};if(!inBounds(q))continue;const k=terrainKey(q);if(!Number.isFinite(terrainMultiplier(brush))&&setupSlots.some(slot=>terrainKey(slot.position)===k))continue;if(brush==='normal')delete next[k];else next[k]=brush;}commitTerrain(next);}
 function exportMap(){const data={version:1,name:mapName,width:mapWidth,height:mapHeight,terrain:Object.fromEntries(Object.entries(terrain).filter(([k])=>{const [x,y]=k.split(',').map(Number);return inBounds({x,y,elevation:0});}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='battlefield.json';a.click();URL.revokeObjectURL(url);}
 async function importMap(file:File){try{if(file.size>100000)throw new Error('Map file too large');const data=JSON.parse(await file.text());if(data.version!==1||!Number.isInteger(data.width)||!Number.isInteger(data.height)||data.width<8||data.width>30||data.height<8||data.height>30||!data.terrain||typeof data.terrain!=='object'||Array.isArray(data.terrain))throw new Error('Invalid battlefield file');const next:Record<string,Terrain>={};for(const [k,v] of Object.entries(data.terrain)){const [x,y]=k.split(',').map(Number);if(k!==`${x},${y}`||!Number.isInteger(x)||!Number.isInteger(y)||x%5||y%5||x< -10||y< -10||x> -10+(data.width-1)*5||y> -10+(data.height-1)*5||!['normal','wall','blocked','difficult','water','hazard'].includes(String(v)))throw new Error('Invalid terrain tile');if(v!=='normal')next[k]=v as Terrain;}setMapWidth(data.width);setMapHeight(data.height);setMapName(typeof data.name==='string'?data.name.slice(0,80):'Battlefield');setTerrain(next);setEditorHistory([]);setEditorFuture([]);setPlacements({});setError('');}catch(e){setError(e instanceof Error?e.message:'Map import failed');}}
